def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    size = len(ranks)
    tree = [0] * (size + 1)
    result = []

    for i, value in enumerate(a):
        rank = ranks[value]
        count_le = 0
        p = rank
        while p:
            count_le += tree[p]
            p -= p & -p

        result.append(min(i, k) - count_le)

        p = rank
        while p <= size:
            tree[p] += 1
            p += p & -p

        if i >= k:
            p = ranks[a[i - k]]
            while p <= size:
                tree[p] -= 1
                p += p & -p

    return result
